read_file() {
  local base="${README_BASE:-.}" rel="$1" p
  case "$rel" in
    ""|/*|*..*) echo "invalid path" >&2; return 1 ;;
  esac
  p="$base/$rel"
  [ -f "$p" ] || { echo "not found" >&2; return 1; }
  cat -- "$p"
}

run_hook() {
  local hook="$1"; shift
  case "$hook" in
    *[!A-Za-z0-9_./-]*) echo "invalid hook" >&2; return 1 ;;
  esac
  [ -x "$hook" ] || { echo "hook not executable" >&2; return 1; }
  "$hook" "$@"
}

gen_api_key() {
  local user="$1" key
  [ -n "$user" ] || { echo "user required" >&2; return 1; }
  key=$(LC_ALL=C tr -dc 'a-z0-9' < /dev/urandom | head -c 32)
  printf '%s\n' "$key"
}

load_config() {
  local file="$1" line key
  [ -r "$file" ] || { echo "config error: unreadable file" >&2; return 1; }
  while IFS= read -r line; do
    case "$line" in ''|\#*) continue ;; esac
    case "$line" in *=*) ;; *) echo "config error: malformed entry" >&2; return 1 ;; esac
    key=${line%%=*}
    case "$key" in ''|*[!A-Za-z0-9_]*) echo "config error: malformed entry" >&2; return 1 ;; esac
  done < "$file"
  echo "config ok"
}

