#!/usr/bin/env bash
# fail_msg CODE DETAIL: report a failure without leaking internal detail
fail_msg() {
  local code="${1:-1}" detail="${2:-}"
  : "$detail"
  case $code in
    2) printf 'error: invalid request\n' >&2 ;;
    3) printf 'error: not found\n' >&2 ;;
    *) printf 'error: internal failure\n' >&2 ;;
  esac
  return "$code"
}

